define([],function(){'use strict';var ROOT_SELECTOR='[data-region="course-content"], #region-main .course-content, .course-content';function el(tag,cls,text){var e=document.createElement(tag);if(cls){e.className=cls;}if(text!=null){e.textContent=text;}return e;}function percentOf(done,total){return total>0?Math.round((done/total)*100):0;}function attentionRow(item,cls){if(item.url){var a=el('a','unics-staff-attention '+cls,item.label);a.href=item.url;return a;}return el('p','unics-staff-attention '+cls,item.label);}function renderAttention(data){if(document.querySelector('.unics-staff-head')){return;}var root=document.querySelector(ROOT_SELECTOR);if(!root||!root.parentNode){return;}var attention=data.attention||{};var head=el('div','unics-staff-head');if(attention.grading){head.appendChild(attentionRow(attention.grading,'unics-staff-attention-grading'));}if(attention.stuck){head.appendChild(attentionRow(attention.stuck,'unics-staff-attention-stuck'));}if(!attention.grading&&!attention.stuck){if(!data.strings||!data.strings.allClear){return;}head.appendChild(el('p','unics-staff-clear',data.strings.allClear));}root.parentNode.insertBefore(head,root);}function renderSectionProgress(li,secData,strings){if(!li||!secData||li.querySelector('.unics-staff-sec')){return;}var done=secData.done||0;var total=secData.total||0;if(total<=0){return;}var wrap=el('div','unics-staff-sec');wrap.setAttribute('role','progressbar');if(strings.sectionName){wrap.setAttribute('aria-label',strings.sectionName);}wrap.setAttribute('aria-valuenow',String(done));wrap.setAttribute('aria-valuemin','0');wrap.setAttribute('aria-valuemax',String(total));if(secData.aria){wrap.setAttribute('aria-valuetext',secData.aria);}wrap.appendChild(el('div','unics-staff-sec-bar')).style.width=percentOf(done,total)+'%';wrap.appendChild(el('span','unics-staff-sec-label',secData.label||''));var badges=li.querySelector('[data-region="sectionbadges"]');if(badges){badges.appendChild(wrap);return;}var header=li.querySelector('.course-section-header');if(header&&header.parentNode){header.parentNode.insertBefore(wrap,header.nextSibling);}}function enhanceActivity(li,info){if(!li||!info||li.querySelector('.unics-staff-chips')){return;}var grid=li.querySelector('.activity-grid');if(!grid){return;}var box=el('div','unics-staff-chips');if(info.doneLabel){box.appendChild(el('span','unics-staff-chip unics-staff-chip-done',info.doneLabel));}if(info.gradingLabel){if(info.gradingUrl){var g=el('a','unics-staff-chip unics-staff-chip-grading',info.gradingLabel);g.href=info.gradingUrl;box.appendChild(g);}else{box.appendChild(el('span','unics-staff-chip unics-staff-chip-grading',info.gradingLabel));}}if(info.stuckLabel){if(info.stuckUrl){var s=el('a','unics-staff-chip unics-staff-chip-stuck',info.stuckLabel);s.href=info.stuckUrl;box.appendChild(s);}else{box.appendChild(el('span','unics-staff-chip unics-staff-chip-stuck',info.stuckLabel));}}if(!box.firstChild){return;}grid.appendChild(box);}return{init:function(data){try{data=data||{};var root=document.querySelector(ROOT_SELECTOR);if(!root||!data.classSize){return;}document.body.classList.add('unics-staff-course');renderAttention(data);var cms=data.cms||{};Object.keys(cms).forEach(function(cmid){var li=document.getElementById('module-'+cmid);if(li){enhanceActivity(li,cms[cmid]);}});var sections=data.sections||{};Object.keys(sections).forEach(function(num){var sec=document.getElementById('section-'+num);if(sec){renderSectionProgress(sec,sections[num],data.strings||{});}});}catch(e){if(window.console){console.warn('unics course_staff',e);}}}};});
